	title ' Scaling'***********************************************************************			   *	SCALING		   *			   *********************************************************************************************************************************************			   *	Copyright (C) 1987-1988	   *	All Rights Reserved		   *	Apple Computer, Inc.	   *			   ********************************************************************************************************************************************** This file contains the code that is used to derive a font of* a given size.** NOTES FOR SCALING:** (1)  strikePtr is the base address of the source bitmap* (2)  rowBytes is	its width in bytes (always even)* (3)  temp is the	starting column of the source rectangle*      (where the first column is numbered 0)* (4)  imWidth is the width of the source rectangle in pixels*       (a single-pixel character would	have imWidth = 1)* (5)  chHeight is	the source font height*      (a single-row font would have chHeight = 1)** (6)  nStrikePtr,	newRowBytes, currPixel, newImWidth, and	newChHeight*      are the corresponding values for the destination** (7)  the point size of the source font is mBestSize, and	of the*      destination	font mWantSize, so we want to scale by*      mWantSize/mBestSize. This ratio	has been computed once (using*      integer disvision); the results	are in quotient and	remainder.*      (There is also a table of multiples of the ratio, rounded up*      to the nearest integer; the table only covers very small values*      but we can make it larger if we	want to.)** * Warning:** This file contains many equates that are found elsewhere in the system.*** Entry Points**	ScaleFont** Change History** xx Jan 87	Bennet Marks** Original Code by Bennet Marks using the scaling algorithms * developed by Art Cabral.** Spring 88	Steven Glass** Code modified to be built with MAX.** 11 Jun 88	Steven Glass** Modified code to work in ROM.** 04 Oct 88	Sue Dumont** Added new field to Apple IIGS font header in order to support larger* fonts.  This field is the high word of the offset to the offset/width table,* "highOwTLoc".  The IIGS font header is now 14 bytes long.* NOTE: the offset still remains relative to the low word position of the offset.*** 10 Apr 89	Steven Glass** Change font version from 102 to 105 to make graphics studio work.** 6-Jan-91	Dave Lyons** Fixed a bug at CalcTablePtrs where we were losing bit 15 of owTOffset,* instead of shifting it into hiOwTOffset.** 17-Jan-91	Dave Lyons** Optimized out a few dozen LDA<, PHA sequences (into PEIs).** 21-Apr-91	Dave Lyons & Ben Koning** Fixed a bug near CalcTablePtrs where we were trying to add two values* at once without bringing the carry over at each step.** 22-Apr-91** Ben made a speed improvement at XLoop, around 3..4%.** 8-Mar-93 SS** Small optimization: consolidated all _DisposeHandle calls into one subr.***********************************************************************		include 'm16.util'	include 'm16.locator'	include 'm16.memory'	include 'm16.intmath'	include 'm16.quickdraw'		include 'special.macros'				title ' QuickDraw Equates';; These are the QuickDraw E1Vectors;ToSlab	equ $E01E00ToSlice	equ $E01E00ToStuffBig	equ $E01E00StdText	equ $E01E04StdLine	equ StdText+4StdRect	equ StdLine+4StdRRect	equ StdRect+4StdOval	equ StdRRect+4StdArc	equ StdOval+4StdPoly	equ StdArc+4StdRgn	equ StdPoly+4StdPixels	equ StdRgn+4StdComment	equ StdPixels+4StdTxMeas	equ StdComment+4StdTxBnds	equ StdTxMeas+4StdGetPic	equ StdTxBnds+4StdPutPic	equ StdGetPic+4PortLoc2ZP	equ StdPutPic+4UserPat2ZP	equ PortLoc2ZP+4GetPenPReady	equ UserPat2ZP+4GetBackPReady	equ GetPenPReady+4Pen2ZP	equ GetBackPReady+4Back2ZP	equ Pen2ZP+4RotatePat	equ Back2ZP+4GetMaskReady	equ RotatePat+4Mask2ZP	equ GetMaskReady+4ExpandMask	equ Mask2ZP+4RotateMask	equ ExpandMask+4RotateLong	equ RotateMask+4PreDraw	equ RotateLong+4XSetup	equ PreDraw+4DrawRectB	equ XSetup+4DrawRect	equ DrawRectB+4SliceSetup	equ DrawRect+4vShiftStay	equ SliceSetup+4	; these are not used internally!vXShiftStay	equ VShiftStay+4	; things down.  They are providevShiftOut	equ vXShiftStay+4vXShiftOut	equ VShiftOut+4BMakeMinRect	equ vXShiftOut+4MakeMinRect	equ BMakeMinRect+4ShieldCursor	equ MakeMinRect+4UnShieldCursor	equ ShieldCursor+4SetUpPortRegions	equ UnShieldCursor+4SetUpScanPtrs	equ SetUpPortRegions+4FreePortRegions	equ SetUpScanPtrs+4Free1Region	equ FreePortRegions+4Free2Regions	equ Free1Region+4Free3Regions	equ Free2Regions+4UnlockBufferHandle	equ Free3Regions+4Init1Region	equ UnlockBufferHandle+4Init2Regions	equ Init1Region+4Init3Regions	equ Init2Regions+4Seek1Region	equ Init3Regions+4Seek2Regions	equ Seek1Region+4Seek3Regions	equ Seek2Regions+4InitRgn	equ Seek3Regions+4SeekRgn	equ InitRgn+4Join1Buffer	equ SeekRgn+4Join2Buffers	equ Join1Buffer+4Join3Buffers	equ Join2Buffers+4SetSlabAdr	equ Join3Buffers+4SetSliceAdr	equ SetSlabAdr+4SetStuffAdr	equ SetSliceAdr+4BlowItUp	equ SetStuffAdr+4PutPictStuff	equ BlowItUp+4AddToPoly	equ PutPictStuff+4OpenPicture	equ AddToPoly+4PicComment	equ OpenPicture+4ClosePicture	equ PicComment+4DrawPicture	equ ClosePicture+4KillPicture	equ DrawPicture+4GimmeVersion	equ KillPicture+4v_FrRgn	equ GimmeVersion+4v_PRgn	equ v_FrRgn+4v_ERgn	equ v_PRgn+4v_IRgn	equ v_ERgn+4v_FRgn	equ v_IRgn+4v_FrRect	equ v_FRgn+4v_PRect	equ v_FrRect+4v_ERect	equ v_PRect+4v_IRect	equ v_ERect+4v_FRect	equ v_IRect+4DChar	equ v_FRect+4DText	equ DChar+4DCString	equ DText	; always the sameBChar	equ DText+4BText	equ BChar+4BCString	equ BText	; always the sameValidChar	equ BText+4GetNextChar	equ ValidChar+4CalcDrawStatus	equ GetNextChar+4TextAndMinRect	equ CalcDrawStatus+4CalcTextBounds	equ TextAndMinRect+4SetUpFontInfo	equ CalcTextBounds+4SetUpBufInfo	equ SetUpFontInfo+4GetTextHandle	equ SetUpBufInfo+4ClearBufPart	equ GetTextHandle+4PutChar	equ ClearBufPart+4BumpPen	equ PutChar+4CleanUpBuffer	equ BumpPen+4PutLine	equ CleanUpBuffer+4PutRgn	equ PutLine+4PutRect	equ PutRgn+4CullPoints	equ PutRect+4SortPoints	equ CullPoints+4PackRgn	equ SortPoints+4RgnOp	equ PackRgn+4PutOval	equ RgnOp+4BumpOval	equ PutOval+4InitOval	equ BumpOval+4SetTB	equ InitOval+4ResetTB	equ SetTB+4StyleText	equ ResetTB+4StyleExtents	equ StyleText+4DoBold	equ StyleExtents+4DoUnderLine	equ DoBold+4StdConic	equ DoUnderLine+4	; vectors added for	new ROMvDrawConic	equ StdConic+4	; 22 Aug 86 SEGvSetScaleAndMap	equ vDrawConic+4DrawCursor	equ vSetScaleAndMap+4UndrawCursor	equ DrawCursor+4vAngleFromSlope	equ UndrawCursor+4vSlopeFromAngle	equ vAngleFromSlope+4RgnBlt	equ vSlopeFromAngle+4 ; vectors added for CopyPixelsSharedMRSetup	equ RgnBlt+4	; 21 Nov 86 SEGShareShieldStuff	equ SharedMRSetup+4	title ' Font Equates';; These are the offsets used to get into fonts;O_V	equ 0	;vertical coordinate of pointO_H	equ 2	;horizontalO_V1	equ 0	;rectangle upper left vertical coord.O_H1	equ 2	;rect. UL horizontalO_V2	equ 4	;rect. lower right vertical coord.O_H2	equ 6	;rect. LR horizontalO_portInfo	equ 0	;portInfo in grafPortO_boundsRect	equ 8	;boundsRect in portInfoO_font	equ 116	;font handle in grafport;O_fontStyle	equ 4O_fontID	equ 2O_style	equ 4O_size	equ 6O_version	equ 8O_fbrExtent	equ 10	;fbrExtent offsetO_highOwTLoc	equ 12	;high word to offset/width table (4 Oct 88);FFormat	equ 0	;fontTypeFMinChar	equ 2	;firstCharFMaxChar	equ 4	;lastCharFMaxWd	equ 6	;widMaxFBBOX	equ 8	;kernMaxFBBOY	equ 10	;nDescentFBBDX	equ 12	;fRectMaxFBBDY	equ 14	;chHeightFLength	equ 16	;owTLocFAscent	equ 18	;ascentFDescent	equ 20	;descentFLeading	equ 22	;leadingFRaster	equ 24	;rowWords;and some of our own devisingFStrike	equ 26	;font strike;offset/width table	entry indicating an	in-range missing symbol:owMSVal	equ -1;;;    Font Lore offsetso_FontVersion	equ 8o_FamNum	equ 2;o_FLFamNum	equ 0o_FLStyle	equ 2o_FLSize	equ 4o_FLVersion	equ 6o_FLMaxWid	equ 8o_FLFBRXtnt	equ 10o_FLHighOffset	equ 12	;high word of offset to offset/width table;		;SMD - 4 Oct 88;;                copy fscons;;word breakdown constantsbitsInWord	equ 16allBitsOff	equ %0000000000000000allBitsOn	equ %1111111111111111firstBit	equ %1000000000000000firstBitXBAed	equ %0000000010000000lastBit	equ %0000000000000001lastBitXBAed	equ %0000000100000000first12Bits	equ %1111111111110000last4Bits	equ %0000000000001111first13Bits	equ %1111111111111000first14Bits	equ %1111111111111100first15Bits	equ %1111111111111110lowByte	equ $00FFhighByte	equ $FF00last15Bits	equ %0111111111111111;ourFHOS	equ 12	;offset to Mac part of font;		;(for font version 01.01, in bytes);also called:ourHeadLength	equ ourFHOSOurVersion	equ $0101	;font version number matching this code;MHLength	equ 26	;Mac header length (bytes);also called:macHeadLength	equ MHLength;******* SMD - Version 1.02 equates.  Apple IIGS font header now has an additional*       field, "highOwTLoc", the high word of the offset to the offset/width*       table.*** To make graphics studio work we change this version number from 102 to 105.** SEG 10 Apr 89*NewVersion	equ $0105	;new version for scaling fonts   10 Oct 88newFHOS	equ 14	;offset to Mac font record (Version 1.02)newHeadLength	equ newFHOS	;(4 Oct 88)*******scaleSizeErr	equ $1B0C	;must match Font Manager	title ' Direct Page Equates'*******************************	         **  June 15, 1987  3:00 pm    **  BHM  x6245	         **	         *******************************;********************************************************************************  These are the 0-page locations used by the font-scaling shell.  They lie*  on QD II's 3rd 0-page*******************************************************************************;mPortRef	equ 0fontHandle	equ mPortRef+4	;added 6/15/87 - BHMfontHeadPtr	equ fontHandle+4fontRecPtr	equ fontHeadPtr+4strikePtr	equ fontRecPtr+4owTPtr	equ strikePtr+4locTPtr	equ owTPtr+4;nFontHandle	equ locTPtr+4nFontHeadPtr	equ nFontHandle+4nFontRecPtr	equ nFontHeadPtr+4nStrikePtr	equ nFontRecPtr+4nOWTPtr	equ nStrikePtr+4nLocTPtr	equ nOWTPtr+4;sbHandle	equ nLocTPtr+4scaledBytesPtr	equ sbHandle+4flbHandle	equ scaledBytesPtr+4fontLorePtr	equ flbHandle+4;temp	equ fontLorePtr+4;firstChar	equ temp+4lastChar	equ firstChar+2chHeight	equ lastChar+2tableLength	equ chHeight+2		;length of Location table, in bytesowTOffset	equ tableLength+2hiOwTOffset	equ owTOffset+2		;SMD- added 4 Oct 88newFontSize	equ hiOwTOffset+2newAscent	equ newFontSize+2newDescent	equ newAscent+2newChHeight	equ newDescent+2rowBytes	equ newChHeight+2newRowBytes	equ rowBytes+2newStrikeSize	equ newRowBytes+2		;4 Oct 88 - now a longcurrIndex	equ newStrikeSize+4lastIndex	equ currIndex+2currPixel	equ lastIndex+2ImWidth	equ currPixel+2newImWidth	equ ImWidth+2quotient	equ newImWidth+2remainder	equ quotient+2bucket	equ remainder+2lastQuo	equ bucket+2maxB	equ lastQuo+2lastSBIndex	equ maxB+2;mWantSize	equ lastSBIndex+2mBestSize	equ mWantSize+2mUserID	equ mBestSize+2EndOfFSZP1	equ mUserID+2;* These variables are all kept on the third zero page.SrcVSize	equ ChHeightSrcHSize	equ ImWidthDstVSize	equ NewChHeightDstHSize	equ NewImWidthSrcLeft	equ TempDstLeft	equ CurrPixelSrcBase	equ StrikePtrSrcWidth	equ RowbytesDstBase	equ nStrikePtrDstWidth	equ NewRowbytesVError	equ EndOfFSZP1HError	equ VError+2ScratchHandle	equ HError+2SrcLimit	equ ScratchHandle+4DstLimit	equ SrcLimit+4DestNibble	equ DstLimit+2LastNibble	equ DestNibble+2ByteLimit	equ LastNibble+2NextFlag	equ ByteLimit+2LoNib	equ NextFlag+2Nibs	equ LoNib+2NextNib	equ Nibs+2SrcCtr	equ NextNib+2SrcBuf	equ SrcCtr+2DstBuf	equ SrcBuf+4HInc	equ DstBuf+4SrcPtr	equ HInc+2DstPtr	equ SrcPtr+4LastOut	equ DstPtr+4ThisOut	equ LastOut+2ThisWord	equ ThisOut+2HowFarToShift	equ ThisWord+2LeftMask	equ HowFarToShift+2RightMask	equ LeftMask+2RightPos	equ RightMask+2DstRightMask	equ RightPos+2DstRightPos	equ DstRightMask+2;;added 1/19/87 10:30 am:SrcBufSize	equ DstRightPos+2DstBufSize	equ SrcBufSize+2DstY	equ DstBufSize+2DstCtr	equ DstY+2DstCnt	equ DstCtr+2SrcVal	equ DstCnt+2SrcWord	equ SrcVal+2SrcCnt	equ SrcWord+2DstWord	equ SrcCnt+2DstWords	equ DstWord+2DstRight	equ DstWords+2;; New direct page location Added 11 Jun 88;ActionIndex	equ DstRight+2;; New equates added 11 Jun 88;CopyIndex	equ 0ShiftIndex	equ 2StretchIndex	equ 4ShrinkIndex	equ 6;********************************************************************************  The next 0-page locations live on other 0-pages - the Font Manager's, and*  QD II's 1st.  They are hard-coded to avoid including all their 0-page*  locations (including some name collisions with the Font Scaler stuff).*  Maintainers Beware!*******************************************************************************;UserID	equ $0A	;QD II's 1st 0-pagePortRef	equ $24	;QD II's 1st 0-page;BestSize	equ $8E	;FM's 0-pageWantSize	equ $96	;FM's 0-page;	title ' Forward References';-----------------------------------------------;;   Forward address	and entries;;-----------------------------------------------	ENTRY CleanUpScaling	ENTRY ToAction	ENTRY ShrinkText	ENTRY StretchText	ENTRY ShiftText	ENTRY CopyText	ENTRY ToMerge	ENTRY SetupScaling	ENTRY ScaleBits	ENTRY ScaleByte	ENTRY TablesNStrike	ENTRY ClearNewStrike	ENTRY SetNewHdrVals	ENTRY CalcNewFntPtrs	ENTRY CalcNewFntSz	ENTRY InitScaling	ENTRY InitByteScaler	ENTRY SetUp2Bufs	ENTRY CalcFontPtrs	ENTRY FntMgr2FntSclr	ENTRY DisposeAHandle	title ' Scale Font'*****************************************************************ScaleFont	PROC EXPORT**			        *  This subroutine scales the current font by the scale factor      *  wantSize/bestSize.  The handle for the new font is left in x,a.  *			        *  If a memory error is encountered during the scaling process,     *  then the routine	returns with the carry set and the error code   *  in the acc.  Otherwise it returns with the carry clear.	        *			        *  In its present form, the code has been written more for clarity  *  than for speed; little optimizing has been done.  Next pass,     *  people.			        *			        *  For convenience with use by the Font	Manager, ScaleFont (and in  *  particular FntMgr2FntSclr) expects to find the desired size in   *  y, the userID in	the acc., and the current (best-so-far)	size in *  x (that last could be picked up from	the font itself, but why    *  mess around?)			        *			        *** Inputs:*	on direct page** Outputs:*	a-reg   Low word of font handle (or error code)*	x-reg   high word of font handle*	carry   set if error, clear if no error** External Refs:*	lots** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 14 Jan 87	Bennet Marks** Started** 15 Jun 87	Bennet Marks** Last Modified*****************************************************************;;	phd;	jsl FntMgr2FntSclr;	jsl CalcFontPtrs;	jsl SetUp2Bufs	bcc NoErr1	sta temp	brl Error1;NoErr1		;;----------------------------------------------------------;; I init the byte scaler first because InitScaling makes; calls to ScaleByte.;	jsl InitByteScaler;	jsl InitScaling******  some error handling added here - BHM	6/15/87*****	bcc NoErr2	sta temp	bra Error2;NoErr2		;	jsl CalcNewFntSz;	bcc NoErr3	sta temp	bra Error3NoErr3		;	jsl CalcNewFntPtrs	;11 Oct 88 - SMD	bcc NoErr3a	;carry set if a size error occurred.	sta temp	;size error code	bra Error4;NoErr3a	jsl SetNewHdrVals	bcc NoErr4	sta temp	brl Error4NoErr4		;	jsl ClearNewStrike;	jsl TablesNStrike;	lxy flbHandle	;8-Mar-93 SS	jsr DisposeAHandle	lxy sbHandle	;8-Mar-93 SS	jsr DisposeAHandle;	jsl CleanUpScaling;;unlock old font:	ldy #4	lda [fontHandle],y	and #$7FFF	sta [fontHandle],y;	ldx nFontHandle+2	lda nFontHandle;		clc	;to mark no error;	pld	rtl;Error4		;	lxy nFontHandle 	;8-Mar-93 SS	jsr DisposeAHandleError3		;	lxy ScratchHandle 	;8-Mar-93 SS	jsr DisposeAHandleError2		;	lxy flbHandle	;8-Mar-93 SS	jsr DisposeAHandle	lxy sbHandle	;8-Mar-93 SS	jsr DisposeAHandleError1		;;;unlock old font:	ldy #4	lda [fontHandle],y	and #$7FFF	sta [fontHandle],y;	lda temp	;error code	sec	;signal the error	pld	rtl	ENDP	EJECT********************************************************************************GetportFontPtr	PROC Export** Description:	This routine derefs the current grafports font handle and*	returns the derefed version of it in fontHeadPtr. This should*	be called by any routine that wants to look at the font *	record directly. It knows about fast fonts, and it knows how* 	to use them!** NOTE:	*** Inputs:	NotMuch** Outputs:	FontHeadPtr** External Refs:;; Equates for the fastfont record;o_FFAscent	equ 0o_FFDescent	equ o_FFAscent+2o_FFMaxWidth	equ o_FFDescent+2o_FFLeading	equ o_FFMaxWidth+2o_FFrowBytes	equ o_FFLeading+2o_oldFontHandle	equ o_FFRowBytes+2o_StrikeSize	equ o_oldFontHandle+4o_FFSizeofVars	equ o_StrikeSize+4o_FFWidthTable	equ o_FFSizeofVarso_FFOffsetTable	equ o_FFWidthTable+256o_FFEndOfTables	equ o_FFOffsetTable+512;** Entry Points:********************************************************************************	ldy #(O_font+2)	lda [mPortRef],y	;font handle high word	bpl standardFont	; if high bit clear we are using a standard fontloadStdData	sta fontHandle+2	; get the handle to the fastfont stuff	ldy #o_font	lda [mportRef],y	sta fontHandle	lda [fontHandle]	; and deref it...	sta fontHeadPtr	ldy #2	lda [fontHandle],y	sta fontHeadPtr+2;	ldy #o_oldFontHandle ; offset to the old font..	lda [fontHeadPtr],y	; get the old font handle	sta fontHandle	ldy #o_oldFontHandle+2	lda [fontHeadPtr],y	sta fontHandle+2	; set temp to be the old font handle	bra SF0010	; and branch into standard font stuff	standardFont	sta fontHandle+2	dey	dey	lda [mPortRef],y	sta fontHandle;SF0010	lda [fontHandle]	sta fontHeadPtr	ldy #2	lda [fontHandle],y	sta fontHeadPtr+2	rtl	EndP	title ' CalcFontPtrs'*****************************************************************CalcFontPtrs	PROC**  This subroutine gets the current font handle out of the grafport *  and calculates the various pointers associated with it.	It also *  saves a few font	values that it had to fetch during its calc-    *  ulations.  (It also sets rowBytes, because there was no better   *  place to do it.)			        *** Inputs:*	current graf port** Outputs:*	Various font pointers*	Font Values*	rowBytes** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 11 Jan 87	Bennet Marks** Started code.** 15 Jun 87	Bennet Marks** Finished first pass.** 04 Oct 88	Sue Dumont** Removed code which calculated the locTable pointer and the offset/width* table pointer.  This code is now located in the routine "SetUp2Bufs".* This is done because the high word of the offset to offset/width table* is retrieved from "_GetFontLore" in "SetUp2Bufs", which is needed to make* these calculations.** 3/15/89	Mensch* Added call to getPortFontPtr to make getting around fastfonts easy****************************************************************;	jsl GetportFontPtr; was:;	ldy #o_font	;get font handle;	lda [mPortRef],y;	sta fontHandle;	iny;	iny;	lda [mPortRef],y;	sta fontHandle+2;;	lda [fontHandle]	;dereference;	sta fontHeadPtr;	ldy #2;	lda [fontHandle],y;	sta fontHeadPtr+2	ldy #4	lda [fontHandle],y	ora #$8000	;and lock the font for now...	sta [fontHandle],y;	lda [fontHeadPtr]	;offset to Mac header part	asl a	;in bytes	clc	adc fontHeadPtr	sta fontRecPtr	lda fontHeadPtr+2	bcc NoCarry1	inc aNoCarry1		;	sta fontRecPtr+2;	ldy #FMinChar	lda [fontRecPtr],y	sta firstChar;	ldy #FMaxChar	lda [fontRecPtr],y	sta lastChar;	inc a	inc a	inc a	sec	sbc firstChar	asl a	sta tableLength	;length of each table;	lda fontRecPtr	clc	adc #FStrike	sta strikePtr	lda fontRecPtr+2	bcc NoCarry2	inc aNoCarry2	sta strikePtr+2;	ldy #FRaster	lda [fontRecPtr],y	;rowWords	asl a	;rowBytes	sta rowBytes;	rtl	ENDP	title ' SetUp2Bufs'*****************************************************************SetUp2Bufs	PROC**  This subroutine gets the buffer needed for a GetFontLore	call,   *  makes that call,	figures out the largest byte our byte-scaler    *  will have to scale (maxB), and gets a buffer of an appropriate   *  size for the scale results.		        *			        *  The font lore buffer handle will be flbHandle, and the pointer   *  fontLorePtr.  The scaled bytes list buffer will have handle      *  sbHandle, and pointer scaledBytesPtr		        *			        *  If either memory	manager call generates an error, then the       *  routine will return with the carry set, the error code in the    *  acc., and neither buffer allocated.	If no error is generated,   *  SetUp2Bufs returns with carry clear.		        *** Inputs:*	some direct page values.** Outputs:*	flbHandle*	fontLorePtr*	sbHandle*	ScaledBytesPtr** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 11 Jan 87	Bennet Marks** Coding started.** 14 Jan 87	Bennet Marks** First pass complete.** 04 Oct 88	Sue Dumont** Added code from "CalcFontPtrs" which calculates the locTable pointer* and the offset/width table pointer.  I also try to retrieve 14 bytes * from "_GetFontLore" for the additional field, highOwTLoc.*****************************************************************	pha	pha	PushLong #14	;#bytes for font lore rec (Ver 1.02)	pei mUserID	pea $8000	;locked on allocation.	PushLong #0;	_NewHandle	;allocate memory for IIGS font header record;	bcc NoMemErr1;mem error:	plx	plx	rtl;NoMemErr1	pla	sta flbHandle	pla	sta flbHandle+2;	lda [flbHandle]	;deref	sta fontLorePtr	ldy #2	lda [flbHandle],y	sta fontLorePtr+2;	PushWord #0	PushzLong fontLorePtr ;DAL	PushWord #14	;Apple IIGS font header size;	_GetFontLore;	pla	;check # bytes returned to see if we got the	cmp #14	;high word offset field (Version 1.02)	blt NoHighOffset	ldy #o_FLHighOffset	;Version 1.02 -  get highOwTLoc field	lda [fontLorePtr],y	asl a	;offset in bytes	sta hiOwTOffset	bra CalcTablePtrs	NoHighOffset	stz hiOwTOffset	;old version, store zero here	******* moved code here from "CalcFontPtrs" to calculate table pointers* SMD - 4 Oct 88*CalcTablePtrs	ldy #FLength	;low word of offset to offset/width table	lda [fontRecPtr],y	;owTLoc (low word)	asl a	;offset in bytes	sta owTOffset*** added 6-Jan-91 DAL--we were losing bit 15 of owTOffset; now we put it into hiOWTOffset	bcc @1	inc hiOwTOffset@1*** end of 6-Jan-91 DAL;	clc;	adc #FLength;	adc fontRecPtr;	sta owTPtr;	lda fontRecPtr+2;	adc hiOwTOffset	;high offset in bytes;	sta owTPtr+2*** DAL and BAK 21-Apr-91 -- the above code is wrong; this is right*** (If owTLen was very close to $FFFF, it didn't work)*** The above code was trying to compute ***   owTPtr := (highOWTOffset|owTOffset) + #FLength + fontRecPtr; A already contains owTOffset	clc	adc #FLength	sta owTPtr	lda hiOwTOffset	adc #0	sta owTPtr+2; so far, owTPtr = (highOWTOffset|owTOffset) + #FLength	clc	lda owTPtr	adc fontRecPtr	sta owTPtr		lda owTPtr+2	adc fontRecPtr+2	sta owTPtr+2*** end of 21-Apr-91	lda owTPtr	sec	sbc tableLength	sta locTPtr	lda owTPtr+2	bcs NoBorrow1	dec aNoBorrow1	sta locTPtr+2	*******	ldy #o_FLFBRXtnt	lda [fontLorePtr],y;	ldy #FAscent	cmp [fontRecPtr],y	bpl MaxOK1	lda [fontRecPtr],y;MaxOK1	ldy #FDescent	cmp [fontRecPtr],y	bpl MaxOK2	lda [fontRecPtr],y;MaxOK2	ldy #FLeading	cmp [fontRecPtr],y	bpl MaxOK3	lda [fontRecPtr],y;MaxOK3	ldy #FBBDX	cmp [fontRecPtr],y	;fRectMax	bpl MaxOK4	lda [fontRecPtr],y;MaxOK4	sta maxB	;biggest number we need to scale;	pha	pha	pea 0;	lda maxB	;*** redundant 8-Mar-93 SS	inc a	;for 0 entry	inc a	;for good luck	asl a	;bytes from words do ever come;	sta lastSBIndex	inc a	inc a;	pha	pei mUserID	pea $8000	PushLong #0;	_NewHandle;	bcc NoMemErr2;mem err:	sta temp	;error code	plx	plx;;dispose of the already-allocated handle:	lxy flbHandle	;8-Mar-93 SS	jsr DisposeAHandle;	lda temp	;error code	sec	;signal an error	rtl;NoMemErr2		;;	pla	sta sbHandle	pla	sta sbHandle+2;	lda [sbHandle]	;deref	sta scaledBytesPtr	ldy #2	lda [sbHandle],y	sta scaledBytesPtr+2;;carry should still	be clear, but just in case . . .	clc;	rtl	ENDP	title ' CalcNewFntSz'*****************************************************************CalcNewFntSz	PROC**  This subroutine calculates the size of the new, scaled font and  *  allocates a handle of the appropriate size.  The handle is       *  newFontHandle.			        *			        *  CalcNewFntSz also calculates newAscent, newDescent, newChHeight, *  and newRowBytes,	which it needs for the new font size.	        *			        *  If there is a memory error, the routine returns with the	carry   *  set, the error code in the acc., and	no new handle allocated.    *  Also, the routine can generate a "size error" if the requested   *  font is bigger than our font data structure allows for; as       *  usual, acc. and carry will be set accordingly.  Otherwise the    *  routine returns with carry clear.		        ** * NOTE:  strike width in pixels < 2 ** 16* (because it's in the last location table entry)* This also means:*        strike width in bytes < 2 ** 8*        strike width in words < 2 ** 7* ALSO:*        total strike size in words < 2 ** 16* (because the owTLoc, which is in words, must leapfrog* over the strike - and more)* * ALSO:* we can for convenience assume*         total strike size in bytes < 2 ** 16* because every bit of code, in ROM or out, uses a simple asl to* double owTLoc, ignoring the high bit entirely.  Whether this is* a bug or a feature I'll leave for some other time.* END OF NOTE* ** Inputs:*	direct page values.** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 11 Jan 87	Bennet Marks** Coding started.** 02 Feb 87	Bennet Marks** First pass complete.** 07 Oct 88	Sue Dumont** Modified newStrikeSize to be a long which will now allow larger* fonts to be created.  This is possible since owTLoc now has a* high word present in the IIGS font header (highOwTLoc).*****************************************************************;;start with the new	vertical measures:;	ldy #FAscent	lda [fontRecPtr],y		;old ascent	jsl ScaleByte	sta newAscent;	ldy #FDescent	lda [fontRecPtr],y	jsl ScaleByte	sta newDescent;	clc	adc newAscent	sta newChHeight;	ldy #FBBDY	lda [fontRecPtr],y	sta chHeight		;needed for sizing and later;;now do the new strike size -;get old strike width in pixels:;		ldy tableLength	dey	dey	lda [locTPtr],y;(last loc table entry = strike width in pixels);;	pha		;for result	pha;scale it:	pha		;push strike width in pixels	pei mWantSize;	_Multiply		;strike width in pixels * mWantSize;	pla	sta temp		;result of multiplication	pla	sta temp+2;	lda mBestSize	dec a	clc	adc temp		;to round up	sta temp	bcc NoCarry1	inc temp+2NoCarry1	pha		;space for result	pha	pha	pha	PushzLong temp	;DAL	pea 0	pei mBestSize;	_LongDivide		;mWantSize / mBestSize;	pla		;scaling factor result, low word	sta temp	plx		;high word, must be	0 (see note)	beq NoSizeErr1;size error:	plx	plx		;get rid of quotient	brl SizeError;NoSizeErr1	plx	plx		;quotient, unneeded;;now, we may have rounded off as much as 1 pixel from each individual;character image by	doing the whole thing at once, so to compensate:;	lda tableLength	lsr a	clc	adc temp	bcc NoSizeErr2	brl SizeErrorNoSizeErr2;;that's  (an upper bound on) the width in pixels -;now let's boil it down to words (and even bytes);	clc	adc #15		;to round up	lsr a	lsr a	lsr a	and #first15Bits;that's even bytes:	sta newRowBytes;;multiply by height:	PushLong #0	pei newRowBytes	pei newChHeight;	_Multiply;	pla		;result low	sta newStrikeSize	pla		;may have high word for strike size 	sta newStrikeSize+2		; in Version 1.02		;	lda #(newHeadLength+macHeadLength)	;version 1.02 header	clc	adc tableLength	adc tableLength		;two tables	adc newStrikeSize	sta temp		;new strike size, in bytes	lda newStrikeSize+2		;may exceed 64K (SMD 4 Oct 88)	bcc StoreSize	inc aStoreSize	sta temp+2	PushLong #0		;resulting handle	pei temp+2		;high word of size in bytes	pei temp		;low word	pei mUserId	pea $8000	PushLong #0;	_NewHandle		;allocate memory for new	;			; font record	bcc NoMemErr;mem error:	plx	plx	rtl;;code for size error:SizeError	lda #scaleSizeErr		;what the Font Manager calls it	sec		;to signal error	rtl;NoMemErr	pla	sta nFontHandle	pla	sta nFontHandle+2;	clc		;No Error	rtl	ENDP	title ' CalcNewFntPtrs'*****************************************************************CalcNewFntPtrs	PROC**  This subroutine sets all the pointers for the various pieces of*  the new font.*** Inputs:*	none** Outputs:*	carry bit set if size error ** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 03 Feb 87	Bennet Marks** First pass complete.** 07 Oct 88	Sue Dumont** Added high word of strike size.  Also, this routine returns* with the carry bit set if a size error occurs.*****************************************************************;	lda [nFontHandle]	;dereference handle	sta nFontHeadPtr	ldy #2	lda [nFontHandle],y	sta nFontHeadPtr+2;	lda nFontHeadPtr	clc	adc #newHeadLength	;(10 Oct 88) compensate for additional IIGS header field	sta nFontRecPtr	lda nFontHeadPtr+2	bcc NoCarry1	inc a	clc	;keep carry clearedNoCarry1		;	sta nFontRecPtr+2;	lda nFontRecPtr	adc #macHeadLength	sta nStrikePtr	lda nFontRecPtr+2	bcc NoCarry2	inc aNoCarry2	sta nStrikePtr+2;	lda nStrikePtr	clc	adc newStrikeSize	sta nLocTPtr	lda nStrikePtr+2	adc newStrikeSize+2	;add high word of strike size - Version 1.02	bcc NoCarry3	;carry already added (4 Oct 88)** Size Error **	lda #scaleSizeErr	;set error for Font Manager	rtl	;carry is already setNoCarry3		;	sta nLocTPtr+2	lda nLocTPtr	clc	adc tableLength	sta nOWTPtr	lda nLocTPtr+2	bcc NoCarry4	inc a	clcNoCarry4	sta nOWTPtr+2	rtl	ENDP	title ' SetNewHdrVals'*****************************************************************SetNewHdrVals	PROC**  This subroutine finds and/or calculates the values to go	in the  *  new font's header fields (both Gumby header and Mac header), and *  places them in the new headers.		        *			        *  This routine can	generate a "size error", if the requested font  *  is too large to permit a 1-word owTLoc value.  In this case,     *  the error code will be in the acc., and the carry will be set.   *  Otherwise, the routine returns with the carry clear.	        *** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 03 Feb 87	Bennet Marks** First pass complete.** 10 Oct 88	Sue Dumont** Sets font record values for Version 1.02*****************************************************************;	lda #(newHeadLength/2)	;10 Oct 88 - SMD	sta [nFontHeadPtr]		;offset-to-Mac field;	ldy #o_FLFamNum	lda [fontLorePtr],y	ldy #o_FamNum	sta [nFontHeadPtr],y;	ldy #o_FLStyle	lda [fontLorePtr],y	ldy #o_Style	sta [nFontHeadPtr],y;	lda mWantSize	ldy #o_Size	sta [nFontHeadPtr],y******** (10 Oct 88)  This version of the Font Scaler is 1.02.****              Version 1.02 has the additional word, highOwTLoc,****              in the Apple IIGS font header****	lda #newVersion		;Version 1.02	ldy #o_Version	sta [nFontHeadPtr],y;	ldy #o_FBRExtent	lda [fontLorePtr],y	jsl ScaleByte	ldy #o_FBRExtent	sta [nFontHeadPtr],y;;so much for the Gumby header - let's get to the Mac header;	ldy #FFormat	lda [fontRecPtr],y	sta [nFontRecPtr],y;	ldy #FMinChar	lda [fontRecPtr],y	sta [nFontRecPtr],y;	ldy #FMaxChar	lda [fontRecPtr],y	sta [nFontRecPtr],y;	ldy #FMaxWd	lda [fontRecPtr],y	jsl ScaleByte	ldy #FMaxWd	sta [nFontRecPtr],y;	ldy #FBBOX	lda [fontRecPtr],y;assume a non-positive kern for now	eor #allBitsOn	inc a		;invert kern	jsl ScaleByte	eor #allBitsOn		;invert result	inc a	ldy #FBBOX	sta [nFontRecPtr],y;	ldy #FBBDX	lda [fontRecPtr],y	jsl ScaleByte	ldy #FBBDX	sta [nFontRecPtr],y;	lda newChHeight	ldy #FBBDY	sta [nFontRecPtr],y;;calculate new owTLoc:;	lda nFontRecPtr	clc	adc #FLength	sta temp	lda nFontRecPtr+2	bcc NoCarry	inc aNoCarry		;	sta temp+2;	lda nOWTPtr	sec	sbc temp	sta temp	lda nOWTPtr+2	sbc temp+2		;owTLoc has high word	sta temp+2		;in Version 1.02		lsr a		;high word of offset in words	ldy #o_highOwTLoc		;to offset/width table	sta [nFontHeadPtr],y	;store in IIGS font header		lda temp	ror a		;rotate the bit in from the	ldy #FLength		;high word	sta [nFontRecPtr],y	lda newAscent	ldy #FAscent	sta [nFontRecPtr],y;	lda newDescent	ldy #FDescent	sta [nFontRecPtr],y;	eor #allBitsOn	;invert it	inc a	ldy #FBBOY	;for nDescent	sta [nFontRecPtr],y;	ldy #FLeading	lda [fontRecPtr],y	jsl ScaleByte	ldy #FLeading	sta [nFontRecPtr],y;	lda newRowBytes	lsr a	ldy #FRaster	sta [nFontRecPtr],y;	clc	;no errors	rtl	ENDP	title ' ClearNewStrike'*****************************************************************ClearNewStrike	PROC**  This subroutine zeroes out the new font strike (the scaled*  character images	are going to be OR'ed into it).*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 13 Jan 87	Bennet Marks** First pass complete.** 11 Oct 88	Sue Dumont** Rewrote entire routine to zero out the font strike.  This was* done to allow a strike size to be greater than 64K.*****************************************************************	lda nStrikePtr		;use temp ptr for nStrikePtr	sta temp	lda nStrikePtr+2	sta temp+2		lda #0	ldx newStrikeSize+2		;high word of strike size	beq LessThan64KBankLoop	ldy #$FFFENextWord1	sta [temp],y	dey	dey	bne NextWord1	sta [temp]		;zero out last word	inc temp+2	dex	bne BankLoopLessThan64K	ldy newStrikeSize	bra EnterLoopNextWord2	sta [temp],yEnterLoop	dey	dey	bne NextWord2	sta [temp]		;zero out last word		rtl	ENDP	title ' TablesNStrike'*****************************************************************TablesNStrike	PROC**  This subroutine fills in the values for the new offset/width*  table and location table, and places	the scaled character*  images in the new font strike.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 15 Jan 87	Bennet Marks** First pass complete.*****************************************************************;	lda tableLength	dec a	dec a	sta lastIndex;	lda #0	sta currIndex	sta currPixel	;in new strike	sta [nLocTPtr];NextChar		;	ldy currIndex	lda [owTPtr],y	;offset/width value	cmp #owMSVal	bne DefinedChar;;character is not defined:	sta [nOWTPtr],y	lda currPixel	iny	iny	sta [nLocTPtr],y;	cpy lastIndex	beq NoMoreChars;(actually, this really can't happen here - the missing symbol must;be defined)	sty currIndex	bra NextChar;DefinedChar	sta temp	;create new offset/width value	and #lowByte	jsl ScaleByte	sta temp+2;	lda temp	xba	and #lowByte	jsl ScaleByte	xba	ora temp+2;	ldy currIndex;	sta [nOWTPtr],y	;store new offset/width value;	lda [locTPtr],y	sta temp	iny	iny	sty currIndex	lda [locTPtr],y	sec	sbc temp	;image width	beq ImWidth0;;image width NOT 0:	sta ImWidth	jsl ScaleByte	sta newImWidth;;{TIME FOR PIXELMAP	SCALING CODE;;  at this point the image of the character from the source	font;  can be scaled and fed into the new font.;;  The source rectangle starts in column TEMP and ends in;  column TEMP + IMWIDTH - 1 (this is purely pixel notation,;  not QDII rectangle description).  The dest rectangle goes;  from CURRPIXEL to CURRPIXEL + NEWIMWIDTH - 1.;;  Some of the updates in the code below may, in fact, be done;  in and around the map-scaling code.;;;	jsl ScaleBits;;;;END OF PIXELMAP SCALING CODE};;	lda currPixel	clc	adc newImWidth	sta currPixel;and fall into . . .;ImWidth0		;	lda currPixel	ldy currIndex	sta [nLocTPtr],y;	cpy lastIndex	beq NoMoreChars	bra NextChar;NoMoreChars		;;;y has the most recent index	lda #(-1)	sta [nOWTPtr],y;	rtl	ENDP	title ' InitByteScaler and ScaleByte'*****************************************************************InitByteScaler	PROC**  This subroutine creates a table of integer multiples of the      *  scale factor mWantSize/mBestSize, for small integers.  The       *  multiples are rounded up.		        *			        *  It is my assumption that the scaling	that has to be done	on      *  every character offset, character width, and image width	(as     *  well as other values, such as the ascent and descent) will       *  involve so many repeat values, and/or values near each other,    *  that creating and using this list is	time-efficient.	        *			        *  The integers scaled here are 0,1,...,maxB, where maxB =	        *  max{ascent,descent,leading,fbrExtent,fRectMax}.  Each value      *  gets its own word in the list.  lastSBIndex, the index of the    *  last entry we want in the list, is calculated in SetUp2Bufs.     *			        *  (There's no good reason why this routine shouldn't be incorpor-  *  ated into SetUp2Bufs as well.)		        *			        *  The zero entry in the list is pointed to by ScaledBytesPtr.      *** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 16 Jan 87	Bennet Marks** First pass complete.*****************************************************************;	PushWord #0	PushWord #0	pei mWantSize	pei mBestSize;	_UDivide;	pla	sta quotient	pla	sta remainder;	lda mBestSize	dec a	sta bucket	;for rounding up;	lda #0	sta [ScaledBytesPtr] ;multiply by 0	sta lastQuo	ldy #2;NextByte		;	lda bucket	clc	adc remainder	cmp mBestSize	bmi NoCarry;carry:	inc lastQuo	sec	sbc mBestSize;NoCarry		;	sta bucket;	lda lastQuo	clc	adc quotient	sta lastQuo	sta [ScaledBytesPtr],y;	cpy lastSBIndex	beq NoMoreBytes;	iny	iny	bra NextByte;NoMoreBytes		;	rtl	ENDP*****************************************************************ScaleByte	PROC**  This routine is used to scale small integer values by the scale  *  factor mWantSize/mBestSize.  ScaleByte accesses the list	of      *  multiples set up	by InitByteScaler.		        *			        *  ScaleByte is "a mite twitchy", and is really only designed to be *  used in this particular context.  Values to be scaled must be    *  non-negative, and <= maxB.  See InitByteScaler and SetUp2Bufs    *  for more information.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 13 Jan 87	Bennet Marks** First pass complete.*****************************************************************;	asl a	tay	lda [ScaledBytesPtr],y;;There, there, that	wasn't such a big deal after all, was it?;	rtl	ENDP	title ' FntMgr2FntSclr'*****************************************************************FntMgr2FntSclr	PROC**  This routine moves us from the Font Manager's 0-page to          *  the Font Scaler's (which is QD II's 3rd 0-page).  It saves the   *  bestSize, wantSize, and ProgID that the FM has kindly placed in  *  x, y, and the acc. for us.  It also picks up portRef from        *  QD II for us.			        *** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 13 Jan 87	Bennet Marks** Coding started.** 10 Feb 87	Bennet Marks** First pass complete.*****************************************************************;;put needed values from Font Manager on	stack:	phx	;bestSize	phy	;wantSize	pha	;progID;;get QD II's (first) 0-page:	pha	pha	;for result	PushWord #0	;system	PushWord #4	;QD II Tool Set Number;	_GetWAP	pla	;QD II's (first) 0-page	plx	;junk;	tcd	;now in QuickDrawTwoLand;	lda portRef	pha	lda portRef+2	pha;	tdc	clc	adc #$200	;our (QD II's third) 0-page	tcd;;get back the values:	pla	sta mPortRef+2	pla	sta mPortRef	pla	sta mUserID	pla	sta mWantSize	pla	sta mBestSize;	rtl	ENDP	title ' InitScaling'*****************************************************************InitScaling	PROC** This routine inits a bunch of vars to do the scaling.*** Inputs:*	?** Outputs:*	?** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;	lda maxB	inc a	inc a	sta SrcBufSize;	lda maxB	jsl ScaleByte	inc a	inc a	sta DstBufSize* SrcBufSize and DstBufSize are set by the Font Manager before calling* InitScaling.  They include a word of slop on each end for	each one* (4 words of slop total).	lda SrcBufSize	clc	adc DstBufSize	; leave size in A****************************************************************	asl a	asl a***************************************************************** create the new handle	pha	; save size of handle	pha	; function result	pha	pea 0	; longint size	pha	Pushword mUserId	; whatever	pea $8000	; attributes	pha	; not used (Locinfo)	pha	_NewHandle	pla	plx	sta ScratchHandle	stx ScratchHandle+2	lda [ScratchHandle]	; dereference it	sta SrcBuf	ldy #2	lda [ScratchHandle],y	sta SrcBuf+2	ply	; size of buffer now in Y	dey	dey	lda #0ClearLoop	sta [SrcBuf],y	dey	dey	bpl ClearLoop	lda SrcBufSize	; retrieve src buf len****************************************************************	asl a****************************************************************	clc	; DstBuf is at end of Scratch	adc SrcBuf	sta DstBuf	lda SrcBuf+2	bcc NBPtr	inaNBPtr	sta DstBuf+2	rtl	ENDP	title ' ScaleBits'*****************************************************************ScaleBits	PROC** Scales the one bit per pixels image.*** Inputs:*   SrcHSize       Width in pixels of source*   SrcLeft        First pixel to transfer (temp)*   SrcBase        Points to the first byte in the source*                  bit map. (StrikePtr)*   SrcWidth       width in bytes of source bit map. (RowBytes)**   DstHSize       Width in pixels of destination*   DstLeft        First pixel to transfer (CurrPixel)*   DstBase        Points to the first byte in the destination*                  bit map (nStrikePtr)*   DstWidth       Width in bytes of dest bit map. (newRowBytes)** Outputs:*	?** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda DstHSize	bne SomethingLeft	rtlSomethingLeft		;* Save the current dbr here so can set it safely below.	phb* Set the appropriate stretching or shrinking routine.	jsl SetupScaling	; set Horiz routine* Initialize our endpoints and counters	stz DstY;****  CHANGED TO WORK WITH EVEN BYTE BOUNDARIES THROUGHOUT;* Calculate SrcPtr as SrcBase + bytes(SrcLeft).  We always assume the* top line of SrcRect matches SrcBase.	lda SrcLeft	lsr A	lsr A	lsr A;****  MAKE THIS EVEN:;	and #first15Bits;****  OK;	sta SrcLimit	;temporary storage;	clc	adc SrcBase	sta SrcPtr	lda SrcBase+2	bcc NBSrcBase	inaNBSrcBase	sta SrcPtr+2;	lda srcLeft	clc	adc srcHSize	dec a	lsr a	lsr a	lsr a	and #first15Bits	sec	sbc SrcLimit	sta RightPos	inc a	inc a	sta SrcLimit	;the real thing;* Calculate DstPtr as DstBase + bytes(DstLeft)	lda DstLeft	lsr A	lsr A	lsr A;****  MAKE THIS EVEN, TOO:;	and #first15Bits;****  OK;	sta DstLimit	;temp storage;	clc	adc DstBase	sta DstPtr	lda DstBase+2	bcc NBDstBase	inaNBDstBase	sta DstPtr+2	lda DstLeft	clc	adc DstHSize	dec a	lsr a	lsr a	lsr a	and #first15Bits	sec	sbc DstLimit	sta DstRightPos	inc a	inc a	sta DstLimit	;really & truly;****  END OF CHANGES TO THIS ROUTINE - BHM  x6245  3/20/87;* Set the data bank	to the bank containing the dest pixels.	pei DstPtr+1	plb	plb* Start the real work in the middle.  	bra NBS1* Get first scanline of Src into SrcBufNextSrc	lda SrcPtr	;increment SrcPtr to next scanline	clc	adc SrcWidth	sta SrcPtr	bcc NBS1	inc SrcPtr+2NBS1	ldy SrcLimit	dey	deySrcCopyLoop	lda [SrcPtr],y	sta [SrcBuf],y	;SrcBuf contains one scanline of source	dey	dey	bpl SrcCopyLoopNextSrc2	lda VError	clc	adc DstVSize	sta VError	dea	bpl SrcOkMergeIt	jsl ToMergeSrcOk		;	lda [SrcBuf]	; mask the src on left and right	and LeftMask	sta [SrcBuf]	ldy RightPos	lda [SrcBuf],y	and RightMask	sta [SrcBuf],y	jsl ToAction	ldy DstRightPos	; try masking the right end of	lda [DstBuf],y	; the dest	and DstRightMask	sta [DstBuf],y* we've merged and stretched so now must put result into real* dest buffer.NxtMask		;	ldy DstLimit	; move the words.	dey	deyDstCopyLoop	lda [DstPtr],y	ora [DstBuf],y	sta [DstPtr],y	dey	dey	bpl DstCopyLoop	lda DstPtr	;increment DstPtr to next scanline	clc	adc DstWidth	sta DstPtr	bcc NBD1	inc DstPtr+2NBD1	lda DstY	ina	cmp DstVSize	bpl Done	sta DstY	lda VError	sec	sbc SrcVSize	; subtract increment	sta VError	; VError := VError - Denom.V	bpl NxtMask	bra NextSrc* Entire Scaling complete. We're still on the first zero page, so use* x to get rid of our scratch buffer, clear the carry, and go home.Done	plb	; restore bank	rtl	ENDP	title ' CleanUpScaling'*****************************************************************CleanupScaling	PROC** Disposes of the ScratchHandle*** Inputs:*	ScratchHandle** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lxy ScratchHandle	;8-Mar-93 SS	jsr DisposeAHandle	rtl	ENDP	title ' SetupScaling'*****************************************************************SetupScaling	PROC** Calc horizontal fraction (if necessary) and case jump**** Inputs:*	?** Outputs:*	?** External Refs:	import LMask	import RMask** Entry Points:*	none*	longa on	; mode	longi on****************************************************************** Init error term for DDA	lda SrcVSize	; vertical size of source	lsr A	eor #$FFFF	ina	sta VError	; VError := -Denom.V/2* Now do the rest;****  ALTERED TO WORK ON WORD BOUNDARIES:;	lda SrcLeft	; start with left mask	and #last4Bits	asl A	tax	lda >LMask,x	sta LeftMask	lda SrcLeft	; now right mask	clc	adc SrcHSize	and #last4Bits	asl A	tax	lda >RMask,x	sta RightMask;;; Now calculate a dest right mask and dst right pos	lda DstLeft	clc	adc DstHSize	and #last4Bits	asl A	tax	lda >RMask,x	sta DstRightMask;;	lda DstHSize	cmp SrcHSize	bne NotEqual	lda DstLeft	and #last4Bits	pha	lda SrcLeft	and #last4Bits	cmp 1,s	beq SetCopySetShift	pla	lda #ShiftIndex	sta ActionIndex	clc	rtlSetCopy	pla	lda #CopyIndex	sta ActionIndex	clc	rtlNotEqual	pha	; FixRatio result	pha	bmi Shrinking	lda #StretchIndex	sta ActionIndex	pei SrcHSize	; push denominator (Src width)	pei DstHSize	; push numerator (Dst width)	bra FixRatioShrinking	lda #ShrinkIndex	sta ActionIndex	pei DstHSize	pei SrcHSizeFixRatio	_FixRatio	pla	; this is the error	part	sta HInc	; which we save	pla	; this better be zero	clc	rtl	ENDP	title ' ToMerge'*****************************************************************ToMerge	PROC** ?*** Inputs:*	?** Outputs:*	?** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda SrcPtr	; first bump SrcPtr	clc	adc SrcWidth	sta SrcPtr	bcc StartMerging	inc SrcPtr+2StartMerging	ldy SrcLimit	; set up loop	dey	deySrcMerger	lda [SrcPtr],y	; get the current bits	ora [SrcBuf],y	; retain all black (1's)	sta [SrcBuf],y	; save the combination	dey	dey	bpl SrcMerger	lda VError	clc	adc DstVSize	; add destination size	sta VError	; VError := VError + Numer.V	dea	bmi ToMerge	; loop while VError	<= 0	rtl	; space keeper	ENDP	title ' ToAction'*****************************************************************ToAction	PROC** This is the routine that is called to do the stretching or* or shrinking.  It uses the ActionIndex to transfer control* to the appropriate routine.** Inputs:*	ActionIndex (on the 3rd direct page)** Outputs:*	none** External Refs:	import CopyText	import ShiftText	import StretchText	import ShrinkText** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 11 Jun 88	Steven Glass** This routine replaces the routine "ToStuff" which used self* modifying code to accomplish the same purpose.  This change* makes it possible to run this code in ROM.*****************************************************************	ldx ActionIndex	jmp (ActionTable,X)	ActionTable	dc.w CopyText	; index is 0	dc.w ShiftText	; index is 2	dc.w StretchText	; index is 4	dc.w ShrinkText	; index is 6		ENDP	title ' CopyText'*****************************************************************CopyText	PROC** We need to establish routines which will either (copy) or	* (copy and shift) from src to destination.  * These already exist.  Use them.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	ldy SrcLimit	dey	deyCopyLoop	lda [SrcBuf],y	sta [DstBuf],y	dey	dey	bpl CopyLoop	rtl	ENDP	title ' ShiftText'*****************************************************************ShiftText	PROC** This routine takes the bits in the src part of src buffer	and* moves them to the	dst part of dest buffer.*** Inputs:*	?** Outputs:*	?** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	stz LastOut	; start by initializing this var	ldy #0	; index into src and dest buffer	lda SrcLeft	; look at which bit	in byte is	and #last4Bits	; first to receive new data	pha	lda DstLeft	; look at which bit	in byte is	and #last4Bits	; first to be transfered	cmp 1,s	; if src is less or	equal to	bcs NormalShift	; dest all is well	clc	adc #16	sec	sbc 1,s	asl a	sta HowFarToShift	plaStaggerLoop	lda [SrcBuf],y	sta ThisWord	ldx HowFarToShift	jsl VXShiftOut	sta ThisOut	lda ThisWord	ldx HowFarToShift	jsl VXShiftStay	ora LastOut	dey	dey	bmi SkipThisOne	sta [DstBuf],ySkipThisOne	lda ThisOut	sta LastOut	iny	; bump by 2	iny	cpy DstLimit	; compare to dest limit to see if we	bpl Done	; are done	iny	; Not yet so bump again to point to	iny	; next source	bra StaggerLoopNormalShift		;	sec	sbc 1,s	asl a	sta HowFarToShift	plaShiftLoop	lda [SrcBuf],y	sta ThisWord	ldx HowFarToShift	jsl VXShiftOut	sta ThisOut	lda ThisWord	ldx HowFarToShift	jsl VXShiftStay	ora LastOut	sta [DstBuf],y	lda ThisOut	sta LastOut	iny	iny	cpy DstLimit	bmi ShiftLoopDone	rtl	ENDP	title ' ShrinkText'*****************************************************************ShrinkText	PROC** ?*** Inputs:*	?** Outputs:*	?** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;----------------------------------------------------------;; Initialize DstCnt	& DstWord;	lda DstLeft	; count depends on alignment	and #last4Bits	; in destination	eor #$000F	inc a	sta DstCnt	stz DstWord	; dstword starts as	zero;----------------------------------------------------------;; Initialize SrcCnt	and SrcWord;	lda SrcLeft	and #last4Bits	tax	eor #$000F	inc a	sta SrcCnt	lda [SrcBuf]	xba	cpx #0	beq SkipThisShitagainagain	asl a	dex	bne againagainSkipThisShit	sta SrcWord;----------------------------------------------------------;; Initialize SrcCtr	and DstCtr;	ldy #2	sty SrcCtr	stz DstCtr; initialize HError	stz HError; initialize fast HInc access to make XLoop below a tiny bit faster BAK 4/22/91	lda HInc	sta >HIncAccess+1NextX	lda HError	; count how many src pixels go	ldx #0	; into one dest pixel	clc	; moved up (was just before adc) BAK 4/22/91XLoop	inxHIncAccess	adc #$FFFF	; add HInc, operand stuffed here from above BAK 4/22/91	bcc XLoop;****  GO FOR IT, MARKS !!!;	sta HError	;added 3/23/87 - BHM  x6245;****  CROSS YOUR FINGERS . . . .;	stz SrcVal	; init num src pixels that are setNextShift	asl SrcWord	; look at next bit in src word	bcc NBSV	; if it is clear dont bump SrcVal	inc SrcVal	; bump SrcValNBSV	dec SrcCnt	; are we done with src?	bne CntOkay	lda #16	; get more source word	sta SrcCnt	ldy SrcCtr;	lda [SrcBuf],y;****  ADDED 3/24/87	TO AVOID PICKING UP	INVALID SOURCE WORD:;(this isn't the optimal way to make the change, but right;now it's the easiest);	cpy SrcLimit	bmi SrcWordValid;no, it's not - so feed a 0 in:	lda #0SrcWordValid		;;****  END OF CHANGE	- BHM  x6245;	iny	iny	sty SrcCtr	xba	sta SrcWordCntOkay	dex	; have we collapsed	enough bits	bne NextShift	lda SrcVal	; if SrcVal not zero then we want	cmp #1	; carry set here	rol DstWord	; and rotated into dest word	dec DstCnt	bne NextX	lda DstWord	xba	ldy DstCtr	sta [DstBuf],y	iny	iny	sty DstCtr	cpy DstLimit	bpl Done	; pray that we really are done	stz DstWord	lda #16	sta DstCnt	bra NextXDone	rtl	ENDP	title ' StretchText'*****************************************************************StretchText	PROC** ?*** Inputs:*	?** Outputs:*	?** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;----------------------------------------------------------;; Initialize DstCnt	& DstWord;	lda DstLeft	; count depends on alignment	and #last4Bits	; in destination	eor #$000F	inc a	sta DstCnt	stz DstWord	; dstword starts as	zero;----------------------------------------------------------;; Initialize SrcCnt	and SrcWord;	lda SrcLeft	and #last4Bits	tax	eor #$000F	inc a	sta SrcCnt	lda [SrcBuf]	xba	cpx #0	beq SkipThisShitagainagain	asl a	dex	bne againagainSkipThisShit	sta SrcWord;----------------------------------------------------------;; Initialize SrcCtr	and DstCtr;	ldy #2	sty SrcCtr	stz DstCtr; initialize HError	stz HError;----------------------------------------------------------;;	php	; put this on stack	to make things evenNextX	ldx #0	; Count Dst pixels	lda HErrorXLoop	inx	clc	adc HInc	bcc XLoop	sta Herror	plp	; get this off stack	asl SrcWord	; set carry from src word	php	; put back on stack	dec SrcCnt	; are we done with this src word	bne RotateX	; no, rotate it in	lda #16	; yes start next one	sta SrcCnt	ldy SrcCtr	; get next src word	from buffer	lda [SrcBuf],y	iny	iny	sty SrcCtr	xba	sta SrcWordRotateX	plp	; now roll that last carry into	php	; the current dest word as many times	rol DstWord	; as required by x	dec DstCnt	bne NotEmpty	lda DstWord	xba	ldy DstCtr	sta [DstBuf],y	iny	iny	sty DstCtr	cpy DstLimit	bpl Done	stz DstWord	; set up for next pass	lda #16	sta DstCntNotEmpty	dex	bne RotateX	bra NextXDone	plp	rtl	ENDP********************************************************************************* Dispose a handle** Inputs:	X,Y = handle** Outputs:	none********************************************************************************DisposeAHandle	PROC	phy	phx	_DisposeHandle	rts	ENDP	title ' LMask and RMask'************************************************************************ Mask Tables***********************************************************************LMask	PROC	DC.B %11111111,%11111111	DC.B %01111111,%11111111	DC.B %00111111,%11111111	DC.B %00011111,%11111111	DC.B %00001111,%11111111	DC.B %00000111,%11111111	DC.B %00000011,%11111111	DC.B %00000001,%11111111	DC.B %00000000,%11111111	DC.B %00000000,%01111111	DC.B %00000000,%00111111	DC.B %00000000,%00011111	DC.B %00000000,%00001111	DC.B %00000000,%00000111	DC.B %00000000,%00000011	DC.B %00000000,%00000001	ENDPRMask	PROC	DC.B %11111111,%11111111	DC.B %10000000,%00000000	DC.B %11000000,%00000000	DC.B %11100000,%00000000	DC.B %11110000,%00000000	DC.B %11111000,%00000000	DC.B %11111100,%00000000	DC.B %11111110,%00000000	DC.B %11111111,%00000000	DC.B %11111111,%10000000	DC.B %11111111,%11000000	DC.B %11111111,%11100000	DC.B %11111111,%11110000	DC.B %11111111,%11111000	DC.B %11111111,%11111100	DC.B %11111111,%11111110	ENDP	END